/* PdaOutReleasePaotMapper.selectAllResultForOutRelease : 박스스캔시 반입,반출승인,반출,홀드,박스 조회하여 결과 처리 */ SELECT '반입' AS dGbn , BL_NO , MBL_NO , DELIVERY_NAME , LAST_POD_STATUS AS IN_LAST_POD_STATUS , IN_CLASS , ALL_INSPECTION_FINISH_YN , XRAY_INSPECTION_CODE , CASE WHEN XRAY_INSPECTION_CODE = '01' THEN '마약' WHEN XRAY_INSPECTION_CODE = '02' THEN '총기' WHEN XRAY_INSPECTION_CODE = '03' THEN '검역' WHEN XRAY_INSPECTION_CODE = '04' THEN '식품,의약품' WHEN XRAY_INSPECTION_CODE = '05' THEN '협업검사' WHEN XRAY_INSPECTION_CODE = '06' THEN '수입검사(기타)' WHEN XRAY_INSPECTION_CODE = 'C' THEN '신고인 검사요청' ELSE '' END AS XRAY_INSPECTION_CODE_NAME , PALN5EM_INSPECTION_CODE , INSPECTION_TYPE , INSPECTION_TYPE_A , INSPECTION_TYPE_B , '' AS NOTIFY_DATE_TIME , SE_INSPECTION_CODE , CRIME_SELECTION_YN , INTELLECTUAL_PROP_YN , INSPECTION_CUSTOMS_YN , BIG_SIZE_YN , '' AS OUT_CLASS , '' AS OUT_APPROVAL_NO , '' AS OUT_SCAN_DATE_TIME , '' AS OUT_LAST_POD_STATUS , CT , WT , '' AS HOLD_REASON , '' AS APPROVAL_CLASS , 0 AS OUT_CT , OD_JOB_NO , CARGO_REFERENCE_NO , IN_PLAN_NO , IN_NO AS KEY_NO , 1 AS SORT_SEQ FROM TB_BMS_IN WITH (NOLOCK) WHERE CARGO_REFERENCE_NO IN (#{item}) UNION ALL SELECT '반출승인' AS dGbn, BL_NO, MBL_NO, '' AS DELIVERY_NAME , '' AS IN_LAST_POD_STATUS, '' AS IN_CLASS, '' AS ALL_INSPECTION_FINISH_YN , '' AS XRAY_INSPECTION_CODE , '' AS XRAY_INSPECTION_CODE_NAME , '' AS PALN5EM_INSPECTION_CODE , '' AS INSPECTION_TYPE , '' AS INSPECTION_TYPE_A , '' AS INSPECTION_TYPE_B , NOTIFY_DATE_TIME AS NOTIFY_DATE_TIME , '' AS SE_INSPECTION_CODE, '' AS CRIME_SELECTION_YN, '' AS INTELLECTUAL_PROP_YN, '' AS INSPECTION_CUSTOMS_YN, '' AS BIG_SIZE_YN , OUT_CLASS, '' AS OUT_APPROVAL_NO, OUT_SCAN_DATE_TIME, '' AS OUT_LAST_POD_STATUS , APPROVAL_CT AS CT, APPROVAL_WT AS WT, '' AS HOLD_REASON, APPROVAL_CLASS, 0 AS OUT_CT , '' AS OD_JOB_NO, CARGO_REFERENCE_NO, 0 AS IN_PLAN_NO , OUT_PLAN_NO AS KEY_NO, 2 AS SORT_SEQ FROM TB_BMS_OUT_PLAN WITH (NOLOCK) WHERE CARGO_REFERENCE_NO IN (#{item}) UNION ALL SELECT '반출' AS dGbn, BL_NO, MBL_NO, '' AS DELIVERY_NAME , '' AS IN_LAST_POD_STATUS, '' AS IN_CLASS, '' AS ALL_INSPECTION_FINISH_YN , '' AS XRAY_INSPECTION_CODE , '' AS XRAY_INSPECTION_CODE_NAME , '' AS PALN5EM_INSPECTION_CODE , '' AS INSPECTION_TYPE , '' AS INSPECTION_TYPE_A , '' AS INSPECTION_TYPE_B , '' AS NOTIFY_DATE_TIME , '' AS SE_INSPECTION_CODE, '' AS CRIME_SELECTION_YN, '' AS INTELLECTUAL_PROP_YN, '' AS INSPECTION_CUSTOMS_YN, '' AS BIG_SIZE_YN , OUT_CLASS, OUT_APPROVAL_NO, OUT_SCAN_DATE_TIME, LAST_POD_STATUS AS OUT_LAST_POD_STATUS , OUT_CT AS CT, OUT_WT AS WT, '' AS HOLD_REASON, '' AS APPROVAL_CLASS, 0 AS OUT_CT , OD_JOB_NO, CARGO_REFERENCE_NO, 0 AS IN_PLAN_NO , OUT_NO AS KEY_NO, 3 AS SORT_SEQ FROM TB_BMS_OUT WITH (NOLOCK) WHERE CARGO_REFERENCE_NO IN (#{item}) UNION ALL SELECT 'HOLD' AS dGbn, '' AS BL_NO, '' AS MBL_NO, '' AS DELIVERY_NAME , '' AS IN_LAST_POD_STATUS, '' AS IN_CLASS, '' AS ALL_INSPECTION_FINISH_YN , '' AS XRAY_INSPECTION_CODE , '' AS XRAY_INSPECTION_CODE_NAME , '' AS PALN5EM_INSPECTION_CODE , '' AS INSPECTION_TYPE , '' AS INSPECTION_TYPE_A , '' AS INSPECTION_TYPE_B , '' AS NOTIFY_DATE_TIME , '' AS SE_INSPECTION_CODE, '' AS CRIME_SELECTION_YN, '' AS INTELLECTUAL_PROP_YN, '' AS INSPECTION_CUSTOMS_YN, '' AS BIG_SIZE_YN , '' AS OUT_CLASS, '' AS OUT_APPROVAL_NO, '' AS OUT_SCAN_DATE_TIME, '' AS OUT_LAST_POD_STATUS , 0 AS CT, 0 AS WT, HOLD_REASON, '' AS APPROVAL_CLASS, 0 AS OUT_CT , OD_JOB_NO, '' AS CARGO_REFERENCE_NO, 0 AS IN_PLAN_NO , 0 AS KEY_NO, 4 AS SORT_SEQ FROM TB_ECM_OD_HOLD WHERE OD_JOB_NO IN (#{item}) AND HOLD_RELEASE_YN <> 'Y' UNION ALL SELECT 'BOX' AS dGbn, P.BL_NO, '' AS MBL_NO, '' AS DELIVERY_NAME , '' AS IN_LAST_POD_STATUS, '' AS IN_CLASS, '' AS ALL_INSPECTION_FINISH_YN , '' AS XRAY_INSPECTION_CODE , '' AS XRAY_INSPECTION_CODE_NAME , '' AS PALN5EM_INSPECTION_CODE , '' AS INSPECTION_TYPE , '' AS INSPECTION_TYPE_A , '' AS INSPECTION_TYPE_B , '' AS NOTIFY_DATE_TIME , '' AS SE_INSPECTION_CODE, '' AS CRIME_SELECTION_YN, '' AS INTELLECTUAL_PROP_YN, '' AS INSPECTION_CUSTOMS_YN, '' AS BIG_SIZE_YN , '' AS OUT_CLASS, '' AS OUT_APPROVAL_NO, '' AS OUT_SCAN_DATE_TIME, '' AS OUT_LAST_POD_STATUS , 0 AS CT, 0 AS WT, '' AS HOLD_REASON, '' AS APPROVAL_CLASS, PP.OUT_CT , P.OD_JOB_NO, P.CARGO_REFERENCE_NO, PP.IN_PLAN_NO , PP.SEQ AS KEY_NO, 5 AS SORT_SEQ FROM TB_BMS_IN_PLAN_PKG PP WITH (NOLOCK) JOIN TB_BMS_IN_PLAN P WITH (NOLOCK) ON PP.IN_PLAN_NO = P.IN_PLAN_NO WHERE PP.PACKING_NO = #{srchPackingNo} AND PP.DELETE_YN = 'N'
AND PP.IN_PLAN_NO = #{srchInPlanNo}
AND P.BL_NO = #{srchBlNo}
ORDER BY SORT_SEQ, KEY_NO

mapper.update:
/* PdaOutReleasePaotMapper.updateOutScanCtFromOutPlan : 반출승인 SCAN수량 업데이트 */
UPDATE TB_BMS_OUT_PLAN
	SET


				OUT_SCAN_CT =
	                CASE
	                    WHEN ISNULL(OUT_SCAN_CT, 0) - 1 < 0 THEN 0
	                    ELSE ISNULL(OUT_SCAN_CT, 0) - 1
	                END


				OUT_SCAN_CT = ISNULL(OUT_SCAN_CT, 0) + 1


		, UPDATE_USER_ID = #{updateUserId}
     	, UPDATE_DATE_TIME = GETDATE()
WHERE 
	OUT_PLAN_NO = #{outPlanNo}
	AND EXISTS (
			SELECT 1
			FROM TB_BMS_IN_PLAN_PKG
			WHERE PACKING_NO = #{srchPackingNo}


						AND OUT_CT = 1


						AND OUT_CT = 0



				AND BL_NO = #{srchBlNo}

		)
	;

UPDATE PP
   SET OUT_CT = #{outCt}
     , UPDATE_USER_ID = #{updateUserId}
     , UPDATE_DATE_TIME = GETDATE()
  FROM TB_BMS_IN_PLAN_PKG PP
  JOIN TB_BMS_IN_PLAN P WITH (NOLOCK)
    ON PP.IN_PLAN_NO = P.IN_PLAN_NO 
 WHERE PP.PACKING_NO = #{srchPackingNo}

   AND PP.IN_PLAN_NO = #{srchInPlanNo}


   AND P.BL_NO = #{srchBlNo}

 ;

/* PdaOutReleasePaotMapper.updateOutScanDtFromBmsOutAndOutPlan2 : 반출승인,반출 반출출고일시 업데이트 */

UPDATE TB_BMS_OUT_PLAN
SET 


			OUT_SCAN_DATE_TIME = ''


			OUT_SCAN_DATE_TIME = GETDATE()


     , UPDATE_USER_ID = #{updateUserId}
     , UPDATE_DATE_TIME = GETDATE()
WHERE 
	OUT_PLAN_NO = #{outPlanNo}


			AND (OUT_SCAN_DATE_TIME <> '' OR OUT_SCAN_DATE_TIME <> '1900-01-01 00:00:00.000');


			AND (OUT_SCAN_DATE_TIME = '' OR OUT_SCAN_DATE_TIME = '1900-01-01 00:00:00.000');




UPDATE TB_BMS_OUT
SET


			OUT_SCAN_DATE_TIME = ''


			OUT_SCAN_DATE_TIME = GETDATE()


	, UPDATE_USER_ID = #{updateUserId}
	, UPDATE_DATE_TIME = GETDATE()
WHERE


			OUT_PLAN_NO = #{outPlanNo}


			OUT_NO IN (#{item})




			AND (OUT_SCAN_DATE_TIME <> '' OR OUT_SCAN_DATE_TIME <> '1900-01-01 00:00:00.000');


			AND (OUT_SCAN_DATE_TIME = '' OR OUT_SCAN_DATE_TIME = '1900-01-01 00:00:00.000');

/* PdaOutReleasePaotMapper.updateOutScanDtFromBmsOutAndOutPlan : 반출승인,반출 반출출고일시 업데이트 */

UPDATE TB_BMS_OUT_PLAN
SET 


			OUT_SCAN_DATE_TIME = #{outScanDateTime}


			OUT_SCAN_DATE_TIME = GETDATE()


     , UPDATE_USER_ID = #{updateUserId}
     , UPDATE_DATE_TIME = GETDATE()
WHERE 
	OUT_PLAN_NO IN (#{item})


			AND (OUT_SCAN_DATE_TIME <> '' OR OUT_SCAN_DATE_TIME <> '1900-01-01 00:00:00.000');


			AND (OUT_SCAN_DATE_TIME = '' OR OUT_SCAN_DATE_TIME = '1900-01-01 00:00:00.000');




UPDATE TB_BMS_OUT
SET


			OUT_SCAN_DATE_TIME = #{outScanDateTime}


			OUT_SCAN_DATE_TIME = GETDATE()


	, UPDATE_USER_ID = #{updateUserId}
	, UPDATE_DATE_TIME = GETDATE()
WHERE 
	OUT_NO IN (#{item})


			AND (OUT_SCAN_DATE_TIME <> '' OR OUT_SCAN_DATE_TIME <> '1900-01-01 00:00:00.000');


			AND (OUT_SCAN_DATE_TIME = '' OR OUT_SCAN_DATE_TIME = '1900-01-01 00:00:00.000');

/* PdaOutReleasePaotMapper.updateOutCtFromBmsInPlanPkg : 박스 반출출고수량 업데이트 */
UPDATE PP
   SET OUT_CT = #{outCt}
     , UPDATE_USER_ID = #{updateUserId}
     , UPDATE_DATE_TIME = GETDATE()
  FROM TB_BMS_IN_PLAN_PKG PP
  JOIN TB_BMS_IN_PLAN P WITH (NOLOCK)
    ON PP.IN_PLAN_NO = P.IN_PLAN_NO 
 WHERE PP.PACKING_NO = #{srchPackingNo}

   AND PP.IN_PLAN_NO = #{srchInPlanNo}


   AND P.BL_NO = #{srchBlNo}

mapper.insert:
/* PdaOutReleasePaotMapper.insertBmsOutScanLog : 출고 스캔로그 저장 */
INSERT INTO TB_BMS_OUT_SCAN (
	  SCAN_NO
	, BL_NO
	, CARGO_REFERENCE_NO
	, SCAN_DATE
	, SCAN_RESULT

	, OUT_NO


	, OUT_STATUS


	, OUT_LINE_NO


	, OUT_FINISH_YN


	, API_CHECK_YN


	, API_DATE_TIME


	, OUT_CLASS

	, SCAN_TYPE
	, REGISTER_USER_ID
	, REGISTER_DATE_TIME
)
VALUES(
	  #{scanNo}
	, #{blNo}
	, #{cargoReferenceNo}
	, CONVERT(VARCHAR(10),GETDATE(),23)
	, #{result}

	, #{outNo}


	, #{outStatus}


	, #{outLineNo}


	, #{outFinishYn}


	, #{apiCheckYn}


	, #{apiDateTime}


	, #{outClass}

	,'PDA'
	, #{registerUserId}
	, GETDATE()
)

		/* PdaOutReleasePaotMapper.insertBmsOutScanLogSelectPkg : 출고 스캔로그 저장 */
		   IF NOT EXISTS(
               SELECT
                   BL_NO
	            FROM TB_BMS_OUT_SCAN
	            WHERE  BL_NO = #{blNo}
					AND SCAN_NO = #{scanNo}
					AND SCAN_RESULT = '완료'
            )
            BEGIN
               INSERT INTO TB_BMS_OUT_SCAN (
         		  SCAN_NO
				, BL_NO
				, CARGO_REFERENCE_NO
				, SCAN_DATE
				, SCAN_RESULT

				, OUT_NO


				, OUT_STATUS


				, OUT_LINE_NO


				, OUT_FINISH_YN


				, API_CHECK_YN


				, API_DATE_TIME


				, OUT_CLASS

				, SCAN_TYPE
				, REGISTER_USER_ID
				, REGISTER_DATE_TIME
	     ) VALUES ( 
	         #{scanNo}
			, #{blNo}
			, #{cargoReferenceNo}
			, CONVERT(VARCHAR(10),GETDATE(),23)
			, #{result}

			, #{outNo}


			, #{outStatus}


			, #{outLineNo}


			, #{outFinishYn}


			, #{apiCheckYn}


			, #{apiDateTime}


			, #{outClass}

			,'PDA'
			, #{registerUserId}
			, GETDATE()
	               );
	        END             
	        ELSE
	          BEGIN 
	               UPDATE 
	                  TB_BMS_OUT_SCAN
	               SET
	                  UPDATE_DATE_TIME = GETDATE()
	               WHERE BL_NO = #{blNo}
		               AND SCAN_NO = #{scanNo}
		               AND SCAN_RESULT  = '완료';
	           END

mapper.select:
/* PdaOutReleasePaotMapper.selectScanLogInfo : 출고 스캔 로그 조회 */
SELECT SCAN_NO , BL_NO , SCAN_DATE , SCAN_RESULT , OUT_STATUS , REGISTER_USER_ID , ISNULL((SELECT tsu.USER_NAME FROM TB_SMS_USER tsu WHERE tsu.USER_ID = tbos.REGISTER_USER_ID),'') AS REGISTER_USER_NAME , REGISTER_DATE_TIME FROM TB_BMS_OUT_SCAN tbos WHERE SCAN_DATE BETWEEN CONVERT(VARCHAR(10), ISNULL(#{srchScanDate},''), 120) AND CONVERT(VARCHAR(10), GETDATE(), 120)
AND OUT_STATUS = #{outStatus}
ORDER BY REGISTER_DATE_TIME DESC

/* PdaOutReleasePaotMapper.selectExistsScanOutCount */
SELECT
	COUNT(*)
FROM
	TB_BMS_OUT_SCAN
WHERE 
	CARGO_REFERENCE_NO = #{cargoReferenceNo}
	AND SCAN_NO = #{srchPackingNo}
	AND SCAN_RESULT = '완료'

/* PdaOutReleasePaotMapper.selectNewCargoReferenceNoFromPkg */
SELECT
	NEW_CARGO_REFERENCE_NO
FROM
	TB_BMS_IN_PLAN_PKG WITH (NOLOCK)
WHERE PACKING_NO = #{srchPackingNo}
	AND DELETE_YN = 'N'

	AND IN_PLAN_NO = #{srchInPlanNo}


	AND BL_NO = #{srchBlNo}
